// Generator for the NZXT Hue 2 module device table.
// Usage: node scripts/openrgb/port-nzxt-hue2-devices.mjs <openrgb-root> <commit>
// Reads Controllers/NZXTHue2Controller/NZXTHue2ControllerDetect.cpp and
// regenerates modules/nzxt-hue2/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'NZXTHue2Controller');
const detect = fs.readFileSync(path.join(family, 'NZXTHue2ControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');

const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+(NZXT[A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.NZXT_VID == null) throw new Error('NZXT_VID not found');

// Extract the RGB channel count from each detector function body: the count is the
// first argument of the spawn_hue(info, name, rgb_channels, fan_channels) call.
const functions = {};
const funcRe = /DetectedControllers\s+(Detect[A-Za-z0-9_]+)\s*\(hid_device_info[\s\S]*?\n\}/g;
for (const m of detect.matchAll(funcRe)) {
  const spawn = m[0].match(/spawn_hue\s*\(\s*info\s*,\s*name\s*,\s*(\d+)/);
  if (spawn) functions[m[1]] = Number.parseInt(spawn[1], 10);
}

// All handlers route into RGBController_NZXTHue2 via spawn_hue; the RGB channel
// count is the first spawn_hue argument.
const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*NZXT_VID\s*,\s*(NZXT[A-Z0-9_]+)\s*\)/g,
)) {
  const pid = constants[m[3].replace(/[()]/g, '').trim()];
  if (pid == null) throw new Error(`unresolved PID ${m[3]} in detector row ${m[1]}`);
  const channels = functions[m[2]];
  if (channels == null) throw new Error(`no spawn_hue rgb_channels found for ${m[2]}`);
  rows.push({ name: m[1], handler: m[2], vid: constants.NZXT_VID, pid, channels });
}
if (rows.length === 0) throw new Error('no NZXT Hue 2 detectors parsed');

const out = path.join(process.cwd(), 'modules', 'nzxt-hue2', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-nzxt-hue2-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  '// Channels is the RGB channel count from the upstream spawn_hue call; 0 marks a',
  '// detector that routes to a different controller and cannot use this protocol.',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, channels: ${d.channels} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} NZXT Hue 2 HID detectors`);